package com.tubasmart.backend.controller;

import com.tubasmart.backend.model.*;
import com.tubasmart.backend.repository.*;
import org.springframework.web.bind.annotation.*;
import java.math.*; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;

@RestController @RequestMapping("/api/reports")
public class ReportController {
 private final InvoiceRepository invoices; private final ReceiptRepository receipts; private final CustomerRepository customers; private final CreditNoteRepository notes; private final ReceiptAllocationRepository allocations; private final InvoiceLineRepository lines; private final FloorRepository floors; private final TenantAllotmentRepository allotments; private final FloorPriceRepository prices;
 public ReportController(InvoiceRepository i,ReceiptRepository r,CustomerRepository c,CreditNoteRepository n,ReceiptAllocationRepository a,InvoiceLineRepository l,FloorRepository f,TenantAllotmentRepository ta,FloorPriceRepository p){invoices=i;receipts=r;customers=c;notes=n;allocations=a;lines=l;floors=f;allotments=ta;prices=p;}
 @GetMapping("/invoice-register") public List<Invoice> invoiceRegister(@RequestParam(required=false) String from,@RequestParam(required=false) String to,@RequestParam(required=false) Long customerId){return invoices.findAll().stream().filter(i->i.getStatus()!=null).filter(i->customerId==null||i.getTenant().getId().equals(customerId)).filter(i->from==null||i.getCreatedAt().toLocalDate().compareTo(LocalDate.parse(from))>=0).filter(i->to==null||i.getCreatedAt().toLocalDate().compareTo(LocalDate.parse(to))<=0).toList();}
 @GetMapping("/receipts") public List<Receipt> receiptRegister(){return receipts.findAll().stream().filter(r->r.getStatus()!=DocumentStatus.CANCELLED).toList();}
 @GetMapping("/credit-notes") public List<CreditNote> creditNotes(){return notes.findAll().stream().filter(n->n.getStatus()!=DocumentStatus.CANCELLED).toList();}
 @GetMapping("/gst") public Map<String,Object> gst(){List<Invoice> inv=issuedSales();List<CreditNote> cn=creditNotes();BigDecimal taxable=sum(inv,x->nvl(x.getSubtotal()).subtract(nvl(x.getDiscount())));return map("invoiceCount",inv.size(),"taxable",money(taxable),"cgst",money(sum(inv,Invoice::getCgst)),"sgst",money(sum(inv,Invoice::getSgst)),"igst",money(sum(inv,Invoice::getIgst)),"creditNotes",cn.size(),"creditNoteTaxable",money(sum(cn,CreditNote::getTaxableValue)),"creditNoteTax",money(sum(cn,CreditNote::getTaxImpact)));}
 @GetMapping("/sac") public List<Map<String,Object>> sac(){Map<String,Map<String,Object>> out=new LinkedHashMap<>();for(InvoiceLine l:lines.findAll()){if(l.getInvoice().getStatus()!=DocumentStatus.ISSUED)continue;String code=l.getSacHsnCode()==null?"UNMAPPED":l.getSacHsnCode();Map<String,Object> r=out.computeIfAbsent(code,k->{Map<String,Object>x=new LinkedHashMap<>();x.put("sacHsnCode",k);x.put("taxable",zero());x.put("tax",zero());x.put("count",0);return x;});r.put("taxable",money(nvl((BigDecimal)r.get("taxable")).add(nvl(l.getTaxable()).signum()==0?nvl(l.getAmount()):l.getTaxable())));r.put("tax",money(nvl((BigDecimal)r.get("tax")).add(nvl(l.getTaxAmount()))));r.put("count",((Integer)r.get("count"))+1);}return new ArrayList<>(out.values());}
 @GetMapping("/ledger/{customerId}") public List<Map<String,Object>> ledger(@PathVariable Long customerId){List<Map<String,Object>> out=new ArrayList<>();for(Invoice i:issuedSales()){if(!i.getTenant().getId().equals(customerId))continue;Map<String,Object>r=row(i.getPeriodTo()==null?i.getBillingPeriod().atEndOfMonth():i.getPeriodTo(),i.getDocumentNumber(),"INVOICE",i.getNetPayable()==null?i.getTotal():i.getNetPayable(),zero());out.add(r);}for(Receipt x:receipts.findAll()){if(x.getStatus()==DocumentStatus.CANCELLED||!x.getTenant().getId().equals(customerId))continue;out.add(row(x.getReceiptDate(),x.getReceiptNumber(),"RECEIPT",zero(),x.getAmount()));}for(CreditNote n:creditNotes()){if(!n.getOriginalInvoice().getTenant().getId().equals(customerId))continue;out.add(row(n.getDate()==null?n.getCreatedAt().toLocalDate():n.getDate(),n.getDocumentNumber(),"CREDIT NOTE",zero(),n.getTotal()));}out.sort(Comparator.comparing(x->String.valueOf(x.get("date"))));return out;}
 @GetMapping("/outstanding") public List<Map<String,Object>> outstanding(){List<Map<String,Object>>out=new ArrayList<>();List<CreditNote> allNotes=creditNotes();for(Invoice i:issuedSales()){BigDecimal value=i.getNetPayable()==null||i.getNetPayable().signum()==0?i.getTotal():i.getNetPayable();BigDecimal paid=allocations.sumAmountByInvoiceId(i.getId());BigDecimal credits=allNotes.stream().filter(n->n.getOriginalInvoice().getId().equals(i.getId())).map(CreditNote::getTotal).reduce(zero(),BigDecimal::add);BigDecimal due=money(value.subtract(paid).subtract(credits));if(due.signum()>0){Map<String,Object>r=new LinkedHashMap<>();r.put("invoice",i.getDocumentNumber());r.put("customer",i.getTenant().getName());r.put("dueDate",i.getDueDate());r.put("invoiceTotal",value);r.put("paid",paid);r.put("creditNotes",credits);r.put("outstanding",due);r.put("ageDays",i.getDueDate()==null?0:Math.max(0,ChronoUnit.DAYS.between(i.getDueDate(),LocalDate.now())));r.put("ageBucket",bucket(r.get("ageDays")));out.add(r);}}return out;}
 @GetMapping("/occupancy") public List<Map<String,Object>> occupancy(){List<Map<String,Object>>out=new ArrayList<>();for(Floor f:floors.findAll()){Map<String,Object>r=new LinkedHashMap<>();r.put("building",f.getBuilding().getName());r.put("floor",f.getFloorName());r.put("area",f.getChargeableArea());r.put("status",f.getStatus());r.put("active",f.isActive());allotments.findAll().stream().filter(a->a.isActive()&&a.getFloor().getId().equals(f.getId())).findFirst().ifPresent(a->{r.put("tenant",a.getTenant().getName());r.put("agreementNumber",a.getAgreementNumber());r.put("monthlyRent",monthly(a));});out.add(r);}return out;}
 @GetMapping("/revenue") public Map<String,Object> revenue(){BigDecimal billed=sum(issuedSales(),Invoice::getTotal);BigDecimal collected=sum(receipts.findAll().stream().filter(r->r.getStatus()!=DocumentStatus.CANCELLED).toList(),Receipt::getAmount);BigDecimal credits=sum(creditNotes(),CreditNote::getTotal);return map("billed",money(billed),"collected",money(collected),"creditNotes",money(credits),"outstanding",money(billed.subtract(collected).subtract(credits)),"invoiceCount",issuedSales().size());}
 @GetMapping("/backup") public Map<String,Object> backup(){return map("exportedAt",OffsetDateTime.now(),"customers",customers.findAll(),"floors",floors.findAll(),"floorPrices",prices.findAll(),"allotments",allotments.findAll(),"invoices",invoices.findAll(),"receipts",receipts.findAll(),"creditNotes",notes.findAll());}
 @GetMapping("/{reportName}") public Object report(@PathVariable String reportName){return switch(reportName){case"invoice-register"->invoiceRegister(null,null,null);case"receipts"->receiptRegister();case"credit-notes"->creditNotes();case"gst"->gst();case"sac"->sac();case"ledger"->Map.of("message","Use /ledger/{customerId}");case"outstanding"->outstanding();case"occupancy"->occupancy();case"revenue"->revenue();case"backup"->backup();default->Map.of("report",reportName,"message","Report not found");};}
 private List<Invoice> issuedSales(){return invoices.findAll().stream().filter(i->i.getStatus()==DocumentStatus.ISSUED).toList();}
 private BigDecimal monthly(TenantAllotment a){return prices.findAll().stream().filter(p->p.isActive()&&p.getFloor().getId().equals(a.getFloor().getId())).map(p->p.getFixedRate()!=null?p.getFixedRate():nvl(p.getPerSqFtRate()).multiply(nvl(a.getFloor().getChargeableArea()))).reduce(zero(),BigDecimal::add).setScale(2,RoundingMode.HALF_UP);}
 private String bucket(Object d){long x=((Number)d).longValue();return x<=30?"0-30":x<=60?"31-60":x<=90?"61-90":"90+";}
 private Map<String,Object> row(LocalDate d,String doc,String type,BigDecimal debit,BigDecimal credit){Map<String,Object>r=new LinkedHashMap<>();r.put("date",d);r.put("document",doc);r.put("type",type);r.put("debit",money(debit));r.put("credit",money(credit));return r;}
 private Map<String,Object> map(Object...a){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)m.put(String.valueOf(a[i]),a[i+1]);return m;}
 private interface Getter<T>{BigDecimal get(T x);} private <T>BigDecimal sum(Collection<T>x,Getter<T>g){BigDecimal s=zero();for(T v:x)s=s.add(nvl(g.get(v)));return s;} private BigDecimal nvl(BigDecimal x){return x==null?zero():x;} private BigDecimal zero(){return BigDecimal.ZERO.setScale(2);} private BigDecimal money(BigDecimal x){return nvl(x).setScale(2,RoundingMode.HALF_UP);}
}
